import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import { networkDelay, requireAdmin, requireAuth } from '../utils';

type UpdateTeamBody = {
  name: string;
};

export const teamsHandlers = [
  http.get(`${env.API_URL}/teams`, async () => {
    await networkDelay();

    try {
      const result = db.team.getAll();
      return HttpResponse.json({ data: result });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(
    `${env.API_URL}/teams/:teamId`,
    async ({ request, params, cookies }) => {
      await networkDelay();

      try {
        const { user, error } = requireAuth(cookies);
        if (error) {
          return HttpResponse.json({ message: error }, { status: 401 });
        }
        const teamId = params.teamId as string;
        requireAdmin(user);
        if (teamId !== user?.teamId) {
          return HttpResponse.json({ message: 'Forbidden' }, { status: 403 });
        }
        const data = (await request.json()) as UpdateTeamBody;
        const result = db.team.update({
          where: {
            id: {
              equals: teamId,
            },
          },
          data: {
            name: data.name,
          },
        });
        if (!result) {
          return HttpResponse.json({ message: 'Not Found' }, { status: 404 });
        }
        await persistDb('team');
        return HttpResponse.json(result);
      } catch (error: any) {
        return HttpResponse.json(
          { message: error?.message || 'Server Error' },
          { status: 500 },
        );
      }
    },
  ),
];
