import { ContentLayout } from '@/components/layouts';
import { TeamSection } from '@/features/teams/components/team-section';
import { UpdateProfile } from '@/features/users/components/update-profile';
import { useUser } from '@/lib/auth';

type EntryProps = {
  label: string;
  value: string;
};
const Entry = ({ label, value }: EntryProps) => (
  <div className="py-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:px-6 sm:py-5">
    <dt className="text-sm font-medium text-gray-500">{label}</dt>
    <dd className="mt-1 text-sm text-gray-900 sm:col-span-2 sm:mt-0">
      {value}
    </dd>
  </div>
);

const ProfileRoute = () => {
  const user = useUser();

  if (!user.data) return null;

  return (
    <ContentLayout title="Profile">
      <div className="space-y-6">
        <div className="overflow-hidden bg-white shadow sm:rounded-lg">
          <div className="px-4 py-5 sm:px-6">
            <div className="flex justify-between">
              <h3 className="text-lg font-medium leading-6 text-gray-900">
                User Information
              </h3>
              <UpdateProfile />
            </div>
            <p className="mt-1 max-w-2xl text-sm text-gray-500">
              Personal details of the user.
            </p>
          </div>
          <div className="border-t border-gray-200 px-4 py-5 sm:p-0">
            <dl className="sm:divide-y sm:divide-gray-200">
              <Entry label="First Name" value={user.data.firstName} />
              <Entry label="Last Name" value={user.data.lastName} />
              <Entry label="Email Address" value={user.data.email} />
              <Entry label="Role" value={user.data.role} />
              <Entry label="Bio" value={user.data.bio} />
            </dl>
          </div>
        </div>
        <TeamSection />
      </div>
    </ContentLayout>
  );
};

export default ProfileRoute;
